// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 fundAmount, address to) public {
        // admissible domain: positive funding, recipient is a plain account that is not c itself
        fundAmount = bound(fundAmount, 1, 1e30);
        vm.assume(to != address(c));
        vm.assume(to != address(0));
        vm.assume(to.code.length == 0);
        vm.assume(uint256(uint160(to)) > 0xffff); // exclude precompiles

        // fund the contract directly so migrateTo has real funds to move
        vm.deal(address(c), fundAmount);

        // setUp deployer (this test contract) is the creator
        c.migrateTo(to);

        assertTrue(address(c).balance == 0);
    }
}
